    }
    // build unique values
    int[] uniq = new int[n];
    int uniqCnt=0;
    int[] cnt = new int[n];
    for(int v:A){
        boolean found=false;
        for(int i=0;i<uniqCnt;i++){
            if(uniq[i]==v){ cnt[i]++; found=true; break;}
        }
        if(!found){ uniq[uniqCnt]=v; cnt[uniqCnt]=1; uniqCnt++; }
    }
    // adjacency
    boolean[][] adj = new boolean[uniqCnt][uniqCnt];
    for(int i=0;i<uniqCnt;i++){
        for(int j=0;j<uniqCnt;j++){
            if(i==j){
